// %% patch phosphorGrid

function lightCell(cell, glyphs) {
  cell.glyph = glyphs[Math.floor(Math.random() * glyphs.length)];
  cell.brightness = 1;
}

function placeRandom(grid, count, glyphs) {
  for (let i = 0; i < count; i++) {
    const r = Math.floor(Math.random() * grid.length);
    const c = Math.floor(Math.random() * grid[0].length);
    lightCell(grid[r][c], glyphs);
  }
}

function placeRow(grid, count, glyphs) {
  const cols = grid[0].length;

  for (let i = 0; i < count; i++) {
    const r = Math.floor(this.rowCursor / cols);
    const c = this.rowCursor % cols;

    lightCell(grid[r][c], glyphs);
    this.rowCursor = (this.rowCursor + 1) % (cols * grid.length);
  }
}

function placeColumns(grid, count, glyphs) {
  for (let i = 0; i < count; i++) {
    const c = Math.floor(Math.random() * grid[0].length);
    this.drops[c] = (this.drops[c] + 1) % grid.length;
    lightCell(grid[this.drops[c]][c], glyphs);
  }
}

function placeDiagonal(grid, count, glyphs) {
  const cols = grid[0].length;

  for (let i = 0; i < count; i++) {
    const c = (this.diagonal + i) % cols;
    const r = (c + this.diagonal) % grid.length;
    lightCell(grid[r][c], glyphs);
  }
}

const phosphorGrid = {
  cols: 80,
  rows: 45,
  fade: 0.95,
  showFPS: true,

  bassMin: 2,
  bassMax: 40,
  trebleMax: 15,

  heavy: ["█", "▓", "▒", "▄", "▀", "▌", "▐"],
  light: ["·", ":", "'", "-", "."],

  place: placeRandom,

  grid: Array.from({ length: 45 }, () =>
    Array.from({ length: 80 }, () => ({
      glyph: " ",
      brightness: 0,
    }))
  ),

  rowCursor: 0,
  drops: Array(80).fill(-1),
  diagonal: 0,
  lastTick: null,

  draw({ clock, audio }) {
    background("#000000");

    // Integer quarter-beats detect both beat wraps and subdivisions.
    if (clock.running) {
      const tick = Math.floor(clock.beat * 8);

      if (this.lastTick === null || tick < this.lastTick) {
        this.lastTick = tick;
      } else if (tick > this.lastTick) {
        // Bound catch-up after a stalled frame or clock jump.
        const first = Math.max(this.lastTick + 1, tick - 3);

        for (let t = first; t <= tick; t++) {
          if (t % 4 === 0) {
            const bass = Math.max(0, Math.min(1, audio.bass || 0));
            const count = Math.floor(
              this.bassMin + bass * (this.bassMax - this.bassMin)
            );

            this.diagonal = (this.diagonal + 1) % this.cols;
            this.place.call(this, this.grid, count, this.heavy);
          } else {
            const treble = Math.max(0, Math.min(1, audio.treble || 0));
            const count = Math.floor(treble * this.trebleMax);

            this.place.call(this, this.grid, count, this.light);
          }
        }

        this.lastTick = tick;
      }
    } else {
      this.lastTick = null;
    }

    const cellW = width / this.cols;
    const cellH = height / this.rows;

    push();
    noStroke();
    textFont("monospace");
    textSize(cellH * 0.9);
    textAlign(CENTER, CENTER);

    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        const cell = this.grid[r][c];

        if (cell.brightness <= 0.01) {
          cell.brightness = 0;
          continue;
        }

        fill(51, 255, 102, cell.brightness * 255);
        text(
          cell.glyph,
          (c + 0.5) * cellW,
          (r + 0.5) * cellH
        );

        cell.brightness *= this.fade;
      }
    }

    if (this.showFPS) {
      fill(51, 255, 102);
      textSize(12);
      textAlign(LEFT, BOTTOM);
      text("FPS " + Math.round(frameRate()), 12, height - 12);
    }

    pop();
  },
};

